'use strict';

const fs = require('fs');
const path = require('path');
const { randomUUID } = require('uuid');

const LOG_DIR = path.join(process.cwd(), 'logs');
const LOG_FILE = path.join(LOG_DIR, 'access.jsonl');

/**
 * Express middleware: appends one JSON line per request to logs/access.jsonl.
 * Attaches req.request_id and the X-Request-ID response header.
 */
function accessLog(options = {}) {
  const file = options.logFile || LOG_FILE;

  return function accessLogMiddleware(req, res, next) {
    const start = process.hrtime.bigint();
    const requestId = randomUUID();

    req.request_id = requestId;
    res.setHeader('X-Request-ID', requestId);

    res.on('finish', () => {
      const durationMs = Number(process.hrtime.bigint() - start) / 1e6;
      const entry = {
        ts: new Date().toISOString(),
        method: req.method,
        path: req.originalUrl || req.url,
        status: res.statusCode,
        duration_ms: Math.round(durationMs * 100) / 100,
        request_id: requestId
      };

      fs.mkdirSync(path.dirname(file), { recursive: true });
      fs.appendFile(file, JSON.stringify(entry) + '\n', (err) => {
        if (err) console.error('[access-log] write failed:', err.message);
      });
    });

    next();
  };
}

module.exports = { accessLog };

