'use strict';

const fs = require('fs');
const path = require('path');
const { expect } = require('chai');
const request = require('supertest');
const { createApp } = require('../src/app');

const LOG_FILE = path.join(process.cwd(), 'logs', 'access.jsonl');

describe('access log middleware', function () {
  beforeEach(function () {
    fs.rmSync(path.dirname(LOG_FILE), { recursive: true, force: true });
  });

  it('appends one well-formed JSON line per request with correct method/status', async function () {
    const app = createApp();

    await request(app).get('/').expect(200);
    await request(app).get('/nope-does-not-exist').expect(404);
    await request(app)
      .post('/echo')
      .send({ hello: 'world' })
      .expect(201);

    const raw = fs.readFileSync(LOG_FILE, 'utf8');
    const lines = raw.split('\n').filter(Boolean);

    expect(lines).to.have.lengthOf(3);

    for (const line of lines) {
      const entry = JSON.parse(line);
      expect(entry).to.include.all.keys(
        'ts', 'method', 'path', 'status', 'duration_ms', 'request_id'
      );
      expect(entry.ts).to.be.a('string');
      expect(Number.isFinite(new Date(entry.ts).getTime())).to.equal(true);
      expect(entry.method).to.be.a('string');
      expect(typeof entry.path).to.equal('string');
      expect(entry.status).to.be.a('number');
      expect(entry.duration_ms).to.be.a('number');
      expect(entry.duration_ms).to.be.at.least(0);
      expect(entry.request_id).to.match(
        /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i
      );
    }

    const entries = lines.map((l) => JSON.parse(l));

    expect(entries[0].method).to.equal('GET');
    expect(entries[0].status).to.equal(200);

    expect(entries[1].method).to.equal('GET');
    expect(entries[1].status).to.equal(404);
    expect(entries[1].path).to.equal('/nope-does-not-exist');

    expect(entries[2].method).to.equal('POST');
    expect(entries[2].status).to.equal(201);
    expect(entries[2].path).to.equal('/echo');
  });

  it('returns X-Request-ID matching the logged request_id', async function () {
    const app = createApp();

    const res = await request(app).get('/').expect(200);
    const requestId = res.headers['x-request-id'];

    expect(requestId).to.match(
      /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i
    );

    const entry = JSON.parse(
      fs.readFileSync(LOG_FILE, 'utf8').trim().split('\n').pop()
    );
    expect(entry.request_id).to.equal(requestId);
  });
});

